var l=[{title:`Τι αλλάζει το σχήμα`,text:`Σε ορισμένες ασκήσεις το κρεμασμένο βάρος μπορεί να κινείται γύρω από τον καρπό ή τον πήχη σας, και ισορροπεί διαφορετικά από έναν αλτήρα. Τα goblet squats, τα deadlifts και οι μεταφορές χρησιμοποιούν το kettlebell με αρκετά απλούς τρόπους. Τα cleans, τα snatches και άλλες βαλλιστικές δεξιότητες προσθέτουν ορμή και απαιτήσεις συντονισμού που μπορεί να είναι πάρα πολλές για αρχάριους.`},{title:`Ξεκινήστε με τα βασικά`,text:`Μάθετε μια ελεγχόμενη άρθρωση ισχίου και ένα απλό deadlift πριν δοκιμάσετε μια αιώρηση (swing), και κάντε goblet squats, deadlifts, κωπηλασίες ή μεταφορές πριν από βαλλιστική εργασία υψηλού συντονισμού. Διαλέξτε ένα kettlebell αρκετά ελαφρύ για επαναλαμβανόμενες σταθερές κινήσεις αλλά αρκετά βαρύ για να σας προκαλεί. Το φύλο ή η ηλικία από μόνα τους δεν μπορούν να σας πουν το σωστό αρχικό βάρος· μετράνε η δύναμη, η εμπειρία σας και η άσκηση που επιλέγετε.`},{title:`Μηχανική της αιώρησης`,text:`Σε μια συνηθισμένη αιώρηση με δύο χέρια, το kettlebell ταξιδεύει από ανάμεσα στα πόδια σας περίπου σε ύψος στήθους, οδηγούμενο από μια ισχυρή έκταση των ισχίων και όχι από το ανέβασμα των χεριών. Κρατήστε τη σπονδυλική στήλη ελεγχόμενη, αφήστε τα γόνατα να λυγίσουν λίγο και καθοδηγήστε το βάρος κατά μήκος του ίδιου τόξου κάθε φορά. Μην μετατρέψετε την άσκηση σε βαθιά καθισιά με μπροστινή ανύψωση.`},{title:`Ασφάλεια και πρόοδος`,text:`Εξασκηθείτε όταν το πάτωμα, τα χέρια σας και ο χώρος γύρω σας είναι καθαρά και στεγνά. Αφήστε αρκετό χώρο μπροστά και πίσω σας για τη διαδρομή του kettlebell. Σταματήστε όταν η λαβή ή η τεχνική της άρθρωσης ισχίου αρχίζει να χαλάει. Περάστε από τα deadlifts και τις ελεγχόμενες αρθρώσεις ισχίου σε σύντομα σετ αιωρήσεων μόνο όταν μπορείτε να κάνετε την κίνηση αξιόπιστα.`},{title:`Χρήση του TrainUp`,text:`Ορίστε με ακρίβεια στο Profile το μέγεθος του δαπέδου, το ύψος του ταβανιού και την επιφάνεια. Το πρόγραμμά σας επιλέγει μόνο ασκήσεις που ταιριάζουν στον χώρο, στην επιφάνεια, στους περιορισμούς και στον συντονισμό σας, κάτι που μετράει για κινήσεις αιώρησης σε μικρό δωμάτιο.`}];var i=[{label:`ACE: τεχνική της αιώρησης kettlebell με δύο χέρια`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`Βιβλιοθήκη ασκήσεων του ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: τεχνική προπόνησης με βάρη (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var s={sections:l,sources:i};export{s as default,l as sections,i as sources};